<?php
$periodId=isset($_GET['id_tahun_ajaran'])?input_id($_GET,'id_tahun_ajaran'):(int)active_period()['id_tahun_ajaran'];
$period=ak_period($periodId);$month=input_text(['bulan'=>$_GET['bulan']??date('Y-m')],'bulan',7);
if(!preg_match('/^[0-9]{4}-(0[1-9]|1[0-2])$/D',$month))throw new InputError('Bulan tidak valid.');
$first=new DateTimeImmutable($month.'-01');$last=$first->modify('last day of this month');
$manage=in_array(current_user()['role'],['admin','kepala_sekolah'],true);
$events=ak_rows('SELECT * FROM ak_kalender WHERE id_tahun_ajaran=? AND mulai<=? AND selesai>=?'.($manage?'':" AND status='disahkan'").' ORDER BY mulai,id',[$periodId,$last->format('Y-m-d'),$first->format('Y-m-d')]);
$edit=$manage && isset($_GET['id'])?ak_one('SELECT * FROM ak_kalender WHERE id=? AND id_tahun_ajaran=?',[input_id($_GET,'id'),$periodId]):null;
$periodOptions=[];foreach(ak_rows('SELECT t.* FROM tahun_ajaran t JOIN ak_periode p USING(id_tahun_ajaran) WHERE p.terverifikasi=1 ORDER BY t.id_tahun_ajaran DESC') as $p)$periodOptions[$p['id_tahun_ajaran']]=$p['tahun_ajaran'].' '.$p['semester'];
?><form method="get" class="panel form-grid filter"><?php ak_hidden('view','kalender');ak_select('id_tahun_ajaran','Periode',$periodOptions,$periodId);ak_field('bulan','Bulan',$month,'month');?><button class="secondary">Tampilkan bulan</button></form>
<section class="panel"><div class="actions"><a class="button secondary" href="<?=e(ak_link('kalender',['id_tahun_ajaran'=>$periodId,'bulan'=>$first->modify('-1 month')->format('Y-m')]))?>">← Sebelumnya</a><a class="button secondary" href="<?=e(ak_link('kalender',['id_tahun_ajaran'=>$periodId,'bulan'=>date('Y-m')]))?>">Hari ini</a><a class="button secondary" href="<?=e(ak_link('kalender',['id_tahun_ajaran'=>$periodId,'bulan'=>$first->modify('+1 month')->format('Y-m')]))?>">Berikutnya →</a></div><h2><?=e($first->format('F Y'))?></h2><div class="calendar-grid"><?php foreach(['Sen','Sel','Rab','Kam','Jum','Sab','Min'] as $day):?><strong class="calendar-cell" style="min-height:24px"><?=e($day)?></strong><?php endforeach;for($i=1;$i<(int)$first->format('N');$i++)echo '<div></div>';for($i=1;$i<=(int)$last->format('d');$i++):$date=$month.'-'.str_pad((string)$i,2,'0',STR_PAD_LEFT);?><div class="calendar-cell <?=$date===date('Y-m-d')?'today':''?>"><strong><?=e($i)?></strong><?php foreach($events as $event)if($event['mulai']<=$date && $event['selesai']>=$date):?><p class="event"><?=e($event['judul'])?> · <?=e($event['jenis'])?><?=$event['status']!=='disahkan'?' ('.e($event['status']).')':''?></p><?php endif;?></div><?php endfor;?></div><?php ak_exports('kalender',['id_tahun_ajaran'=>$periodId]);?></section>
<?php if(!$events):?><div class="notice">Belum ada kegiatan yang dapat ditampilkan. Kalender resmi tidak dibuat secara otomatis.</div><?php endif;foreach($events as $event):?><article class="panel"><h3><?=e($event['judul'])?></h3><p><?=e($event['mulai'])?> — <?=e($event['selesai'])?> · <?=e($event['jenis'])?> · <?=e($event['status'])?></p><p><?=e($event['catatan'])?></p><?php if($manage):?><a class="button secondary" href="<?=e(ak_link('kalender',['id_tahun_ajaran'=>$periodId,'bulan'=>$month,'id'=>$event['id']]))?>">Edit / nonaktifkan</a><?php endif;?></article><?php endforeach;if($manage):?>
<section class="panel"><h2><?=$edit?'Edit kegiatan':'Tambah kegiatan'?></h2><form method="post"><?=csrf_field()?><?php ak_hidden('action','kalender');ak_hidden('id_tahun_ajaran',$periodId);ak_hidden('revision',$edit['revision']??0);if($edit)ak_hidden('id',$edit['id']);?><div class="form-grid"><?php ak_field('judul','Nama kegiatan',$edit['judul']??'');ak_field('mulai','Mulai',$edit['mulai']??'','date');ak_field('selesai','Selesai',$edit['selesai']??'','date');ak_select('jenis','Jenis',array_combine(['Libur','Ujian','Hari Efektif','Agenda'],['Libur','Ujian','Hari Efektif','Agenda']),$edit['jenis']??'Agenda');ak_select('status','Status',['draft'=>'Draft (belum resmi)','disahkan'=>'Disahkan','nonaktif'=>'Nonaktif'],$edit['status']??'draft');?></div><?php ak_field('catatan','Catatan / dasar pengesahan',$edit['catatan']??'');?><button type="submit">Simpan kegiatan</button></form></section><?php endif;?>
